class PriceEngine:
    def __init__(self):
        self.discount_rates = {
            'basic': 0.0,
            'pro': 0.1
        }

    def price(self, plan, amount):
        if plan not in self.discount_rates:
            raise KeyError(f"Unknown plan: {plan}")

        discount_rate = self.discount_rates[plan]
        discounted_price = amount * (1 - discount_rate)
        return round(discounted_price, 2)

# Example usage:
# engine = PriceEngine()
# print(engine.price('basic', 100))  # Output: 100.0
# print(engine.price('pro', 100))    # Output: 90.0
# print(engine.price('premium', 100)) # Raises KeyError

class PriceEngine:
    def __init__(self):
        self.plans = {
            'basic': 1.0,
            'pro': 0.9  # 10% discount
        }

    def price(self, plan, amount):
        if plan not in self.plans:
            raise KeyError(f"Unknown plan: {plan}")

        discounted_price = amount * self.plans[plan]
        return round(discounted_price, 2)

